/**
 * @file MoveDB.js
 * @brief Read-only repository of the moves (C++: class MoveDB : public DataRepository).
 * Built from data/raw/moves-data.js (generated by tools/data/gen-moves.mjs). Every entry is a
 * frozen MoveDefinition:
 *   { id, type, category, power, accuracy, priority, rarity, hits|null, cooldown, tags[],
 *     bypassDefenseBoosts, neverMiss, effects[], learnTypes[] }
 * `cooldown` is the multiplier of the attack delay (1 = normal, < 1 = faster).
 * Effects use the MoveEffectKinds vocabulary (docs/BATTLE_EFFECTS.md).
 * Names and descriptions are NOT data: t('move.<id>') / t('move_desc.<id>').
 */
import { DataRepository, deepFreeze } from '../core/DataRepository.js';
import { MOVES_DATA as GENERATED_MOVES } from '../raw/moves-data.js';
import { MOVES_CONTENT } from '../content/moves-content.js';
import { withContent } from '../core/ContentTables.js';

const MOVES_DATA = withContent(GENERATED_MOVES, MOVES_CONTENT);
import { TypeChart } from '../core/TypeChart.js';
import { MoveEffectKinds } from './MoveEffectKinds.js';
import { MoveTags } from './MoveTags.js';
import { MoveConfig } from '../../config/MoveConfig.js';

/** Move categories (C++: enum class MoveCategory). */
export const MoveCategories = Object.freeze({ PHYSICAL: 'physical', SPECIAL: 'special', STATUS: 'status' });

const KNOWN_KINDS = new Set(Object.values(MoveEffectKinds));
const KNOWN_TAGS = new Set(Object.values(MoveTags));

export class MoveDB extends DataRepository {
  /** @type {MoveDB|null} */
  static _instance = null;

  /** @returns {MoveDB} */
  static getInstance() {
    if (!MoveDB._instance) MoveDB._instance = new MoveDB();
    return MoveDB._instance;
  }

  constructor() {
    super('MoveDB');
  }

  /** @protected @override */
  _build() {
    for (const [id, raw] of Object.entries(MOVES_DATA)) {
      this._entries.set(id, deepFreeze({
        id,
        type: TypeChart.normalize(raw.type) || 'normal',
        category: Object.values(MoveCategories).includes(raw.category) ? raw.category : MoveCategories.STATUS,
        power: Number(raw.power) || 0,
        accuracy: Number(raw.accuracy) || 0,
        priority: Number(raw.priority) || 0,
        rarity: Number(raw.rarity) || 1,
        hits: Array.isArray(raw.hits) ? [...raw.hits] : null,
        cooldown: Number(raw.cooldown) || 1,
        tags: [...(raw.tags || [])],
        bypassDefenseBoosts: raw.bypassDefenseBoosts === true,
        neverMiss: raw.neverMiss === true,
        effects: (raw.effects || []).map((effect) => ({ ...effect })),
        learnTypes: [...(raw.learnTypes || [])]
      }));
    }
  }

  /**
   * @param {string} id
   * @param {string} tag - MoveTags value
   * @returns {boolean}
   */
  hasTag(id, tag) {
    return !!this.getById(id)?.tags.includes(tag);
  }

  /** @override */
  validate() {
    const problems = [];
    for (const move of this._entries.values()) {
      if (!TypeChart.normalize(MOVES_DATA[move.id].type)) problems.push(this._problem(move.id, 'type', MOVES_DATA[move.id].type));
      for (const effect of move.effects) {
        if (!KNOWN_KINDS.has(effect.kind)) problems.push(this._problem(move.id, 'effects', effect.kind));
      }
      for (const tag of move.tags) {
        if (!KNOWN_TAGS.has(tag)) problems.push(this._problem(move.id, 'tags', tag));
      }
      for (const type of move.learnTypes) {
        if (type !== MoveConfig.ANY_TYPE && !TypeChart.normalize(type)) problems.push(this._problem(move.id, 'learnTypes', type));
      }
    }
    if (!this.has(MoveConfig.FALLBACK_MOVE_ID)) problems.push(this._problem(MoveConfig.FALLBACK_MOVE_ID, 'id', MoveConfig.FALLBACK_MOVE_ID));
    return problems;
  }
}
